import{_ as e,o as i,c as n,a3 as r}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Benchmarking QuickJS and Static Hermes","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/static-hermes-runtime/docs/benchmarking.md"},"headers":[],"relativePath":"tools/static-hermes-runtime/docs/benchmarking.md","filePath":"tools/static-hermes-runtime/docs/benchmarking.md","lastUpdated":1791816043000}'),a={name:"tools/static-hermes-runtime/docs/benchmarking.md"};function d(o,t,s,l,h,c){return i(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="benchmarking-quickjs-and-static-hermes" tabindex="-1">Benchmarking QuickJS and Static Hermes <a class="header-anchor" href="#benchmarking-quickjs-and-static-hermes" aria-label="Permalink to &quot;Benchmarking QuickJS and Static Hermes&quot;">​</a></h1><p>This guide explains what the engine comparison measures, how to read its report, and what conclusions its results support. It is intended for plugin authors, Pumpkin developers, runtime and CI contributors, and readers curious about the trade-offs.</p><p>The comparison builds production WebAssembly components and exercises them on a real Pumpkin server. It compares QuickJS, Static Hermes full, and Static Hermes lean. It is a focused workload suite, not a universal JavaScript-engine ranking.</p><h2 id="what-the-comparison-runs" tabindex="-1">What the comparison runs <a class="header-anchor" href="#what-the-comparison-runs" aria-label="Permalink to &quot;What the comparison runs&quot;">​</a></h2><p>The build tool bundles the same benchmark plugin source for each engine:</p><ul><li><strong>QuickJS</strong> bundles JavaScript as an ES module and &quot;componentizes&quot; it with this repository’s QuickJS runtime.</li><li><strong>Static Hermes full</strong> compiles the JavaScript bundle to Hermes bytecode, embeds it in a statically linked Hermes/JSI WASI component, and retains runtime source compilation.</li><li><strong>Static Hermes lean</strong> uses the same precompiled-bytecode execution model but omits runtime source compilation. In lean mode, <code>eval</code> and the <code>Function</code> constructor are unavailable.</li></ul><p>Here, “Static Hermes” means Hermes linked into the WASI component. The plugin’s JavaScript is compiled to Hermes bytecode before the component runs; the benchmark does not translate JavaScript into native Wasm instructions. JIT is disabled for the WASI build. All three are Wasm components executed by Pumpkin’s runtime, not native desktop engine binaries.</p><p>Production builds minify the bundle and enforce the repository’s 5 MiB component limit (5,242,880 bytes). Build flags, toolchain pins, and runtime details are in the <a href="./../README">Static Hermes runtime guide</a> and <a href="./../../../docs/building">build guide</a>.</p><h2 id="run-the-comparison" tabindex="-1">Run the comparison <a class="header-anchor" href="#run-the-comparison" aria-label="Permalink to &quot;Run the comparison&quot;">​</a></h2><p>From the repository root:</p><pre><code>pnpm --filter @pumpkin-plugins/static-hermes-runtime compare-engines
</code></pre><p>The command runs the real-server integration test in <a href="../test/engine-comparison.test.ts">engine-comparison.test.ts</a>. The test builds temporary packages, starts one Pumpkin server for each component, dispatches the benchmark command, collects results, then stops the server. Static Hermes preparation runs automatically when a build needs it; CI also restores and verifies its pinned toolchain before comparing engines in the <a href="../../../.github/workflows/engine-comparison.yml">engine comparison workflow</a>.</p><p>The benchmark plugin and workload definitions are in <a href="../src/benchmark-plugin.ts">benchmark-plugin.ts</a> and <a href="../src/benchmark-workloads.ts">benchmark-workloads.ts</a>. GitHub Actions appends the report to the job summary.</p><h2 id="method-and-scope" tabindex="-1">Method and scope <a class="header-anchor" href="#method-and-scope" aria-label="Permalink to &quot;Method and scope&quot;">​</a></h2><p>Each engine receives the same workload source and input count. The integration test checks that all three engines return matching deterministic checksums for every workload; it also pins expected checksum values for selected string and command fixtures. It checks that:</p><ul><li>every engine reports the same workload identifiers, input counts, and checksums;</li><li>each timed workload has one un-timed warm-up followed by five measured samples;</li><li>the production component is non-empty and within the build-size limit;</li><li>the plugin registers its command and exercises selected real Pumpkin API behavior.</li></ul><p>Workload timing uses JavaScript <code>Date.now()</code>, so samples are reported as integer milliseconds; the clock may be coarser in practice. For each workload, the report shows the median and the minimum-to-maximum range of the five samples. The timer covers the workload body; it does not include component compilation, server startup, plugin loading, or dispatching the outer benchmark command.</p><p>There are 24 timed workloads: 23 deterministic guest-side fixtures and one real Pumpkin API call. The fixture algorithms are representative examples written for this benchmark; they are not executions of the named plugins or Pumpkin’s own command router. Player-directory and other player-oriented fixture workloads use in-memory test data, not connected players.</p><p>The engines run serially in QuickJS, full Hermes, then lean Hermes order, each with a newly started server. The real API workload calls <code>server.getAllPlayers()</code> 10,000 times per sample, or 60,000 calls per engine including the warm-up and five measured samples. The test server has no connected players, so the returned list is empty. The test separately registers and dispatches one real <code>server.command()</code> command, along with event and scheduled-task behavior checks. That command dispatch is API behavior coverage, not a timed command-routing workload.</p><h3 id="workload-inventory" tabindex="-1">Workload inventory <a class="header-anchor" href="#workload-inventory" aria-label="Permalink to &quot;Workload inventory&quot;">​</a></h3><p>“Inputs per sample” is the fixture’s configured loop or request count. It describes work within that particular row; it is not a common unit that makes different rows directly comparable.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Workload</th><th style="text-align:right;">Inputs per sample</th><th>What it represents</th></tr></thead><tbody><tr><td>Synthetic</td><td><code>numeric</code></td><td style="text-align:right;">1,000,000</td><td>Numeric arithmetic baseline</td></tr><tr><td>Synthetic</td><td><code>objects</code></td><td style="text-align:right;">50,000</td><td>Object allocation and traversal</td></tr><tr><td>Synthetic</td><td><code>strings</code></td><td style="text-align:right;">25,000</td><td>String construction followed by joining</td></tr><tr><td>Synthetic</td><td><code>string-construction</code></td><td style="text-align:right;">25,000</td><td>Construction of string parts</td></tr><tr><td>Synthetic</td><td><code>string-join</code></td><td style="text-align:right;">25,000</td><td>Joining a prebuilt dense array of strings</td></tr><tr><td>Synthetic</td><td><code>config-validation</code></td><td style="text-align:right;">1,000</td><td>JSON parsing and configuration validation</td></tr><tr><td>Synthetic</td><td><code>command-routing</code></td><td style="text-align:right;">4,000</td><td>Guest-side tokenization, alias resolution, and route-map lookup</td></tr><tr><td>Synthetic</td><td><code>command-tokenization</code></td><td style="text-align:right;">4,000</td><td>Command tokenization in isolation</td></tr><tr><td>Synthetic</td><td><code>command-route-lookup</code></td><td style="text-align:right;">4,000</td><td>Alias and route-map lookup in isolation</td></tr><tr><td>Synthetic</td><td><code>permission-resolution</code></td><td style="text-align:right;">12,000</td><td>Permission inheritance and context lookup</td></tr><tr><td>Synthetic</td><td><code>player-directory</code></td><td style="text-align:right;">18,000</td><td>Player and home lookups against fixtures</td></tr><tr><td>Synthetic</td><td><code>event-cache</code></td><td style="text-align:right;">20,000</td><td>Lifecycle cache updates</td></tr><tr><td>Synthetic</td><td><code>chat-formatting</code></td><td style="text-align:right;">3,000</td><td>Chat-template formatting and filtering</td></tr><tr><td>Synthetic</td><td><code>scoreboard-rendering</code></td><td style="text-align:right;">12,000</td><td>Scoreboard text rendering</td></tr><tr><td>Synthetic</td><td><code>region-protection</code></td><td style="text-align:right;">20,000</td><td>Region containment and access checks</td></tr><tr><td>Synthetic</td><td><code>world-edit-plan</code></td><td style="text-align:right;">55,296</td><td>Block-edit plan generation</td></tr><tr><td>Synthetic</td><td><code>economy-transfers</code></td><td style="text-align:right;">12,000</td><td>Balance transfer processing</td></tr><tr><td>Synthetic</td><td><code>inventory-stacking</code></td><td style="text-align:right;">2,500</td><td>Inventory stack allocation</td></tr><tr><td>Synthetic</td><td><code>cooldown-rate-limit</code></td><td style="text-align:right;">20,000</td><td>Cooldown and rate-limit checks</td></tr><tr><td>Synthetic</td><td><code>tick-scheduler</code></td><td style="text-align:right;">6,000</td><td>Scheduled-task processing</td></tr><tr><td>Synthetic</td><td><code>audit-history</code></td><td style="text-align:right;">13,000</td><td>Audit-history filtering</td></tr><tr><td>Synthetic</td><td><code>player-state-json</code></td><td style="text-align:right;">1,200</td><td>Player-state JSON round trip</td></tr><tr><td>Synthetic</td><td><code>custom-payload</code></td><td style="text-align:right;">16,384</td><td>Custom payload encoding</td></tr><tr><td>Real API</td><td><code>pumpkin-api</code></td><td style="text-align:right;">10,000</td><td>Calls to <code>server.getAllPlayers()</code></td></tr></tbody></table><p>The string and command rows deliberately separate composite work from selected sub-operations. The composite string workload constructs and joins 25,000 parts; its two component workloads isolate construction and joining. Command routing combines tokenization, alias resolution, and route lookup; the standalone tokenization and lookup rows help show which portion may account for a difference.</p><h2 id="reading-the-report" tabindex="-1">Reading the report <a class="header-anchor" href="#reading-the-report" aria-label="Permalink to &quot;Reading the report&quot;">​</a></h2><p>The current report contains production component sizes, per-workload timings and ratios, and an arithmetic-mean summary.</p><ul><li><strong>Component sizes</strong> are final production component byte counts. Size differences use QuickJS as the baseline: negative means smaller than QuickJS, positive means larger.</li><li><strong>Per-workload timings</strong> show each engine’s median and sample range in milliseconds. Lower time means that engine completed that particular workload sooner in that run.</li><li><strong>QuickJS/full</strong> and <strong>QuickJS/lean</strong> are QuickJS median divided by the corresponding Hermes median. A ratio above 1 means the Hermes median was lower; below 1 means QuickJS was lower. A ratio shown as 1.00x can be a rounded tie, especially for workloads close to the timer’s one-millisecond resolution.</li><li><strong>Average benchmark median</strong> is the arithmetic mean of the 24 per-workload medians. Every workload contributes equally, despite different input counts and different kinds of work. Treat it as a compact report statistic, not a representative plugin or server-performance score.</li></ul><p>The integration test has no timing thresholds. Timing results are diagnostic evidence, while checksum, API behavior, and component-size checks provide pass/fail assertions.</p><h2 id="example-ci-result" tabindex="-1">Example CI result <a class="header-anchor" href="#example-ci-result" aria-label="Permalink to &quot;Example CI result&quot;">​</a></h2><p>The <a href="https://github.com/filiphsps/pumpkin-plugins/actions/runs/38254750702/job/114834399434?pr=99" target="_blank" rel="noreferrer">engine-comparison job linked from PR 99</a> is one reference result. It checked out the PR merge ref at commit <code>2a4cfa19157cfabed67f41de16b199c3fc1c0775</code> on a GitHub-hosted Ubuntu 26.04 runner. The run is evidence for that merge candidate and runner only; it does not describe master or another revision. The job log does not identify the runner’s CPU model. The raw report predates the current report layout; the workload implementations match the inventory documented here, and the table below uses the current workload identifiers.</p><h3 id="component-sizes-in-that-run" tabindex="-1">Component sizes in that run <a class="header-anchor" href="#component-sizes-in-that-run" aria-label="Permalink to &quot;Component sizes in that run&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Engine</th><th style="text-align:right;">Component size</th><th style="text-align:right;">Difference from QuickJS</th></tr></thead><tbody><tr><td>QuickJS</td><td style="text-align:right;">5,081,200 bytes</td><td style="text-align:right;">Baseline</td></tr><tr><td>Static Hermes full</td><td style="text-align:right;">3,643,322 bytes</td><td style="text-align:right;">−1,437,878 bytes (−28.30%)</td></tr><tr><td>Static Hermes lean</td><td style="text-align:right;">2,130,174 bytes</td><td style="text-align:right;">−2,951,026 bytes (−58.08%)</td></tr></tbody></table><p>The QuickJS component was 161,680 bytes below the 5 MiB limit. Lean was 1,513,148 bytes smaller than full in this build. These are sizes for the benchmark plugin and build configuration, not fixed sizes for arbitrary plugins.</p><h3 id="per-workload-results-in-that-run" tabindex="-1">Per-workload results in that run <a class="header-anchor" href="#per-workload-results-in-that-run" aria-label="Permalink to &quot;Per-workload results in that run&quot;">​</a></h3><p>Times are median milliseconds, with minimum–maximum samples in parentheses. The final columns show the QuickJS-to-Hermes ratios defined above.</p><table tabindex="0"><thead><tr><th>Workload</th><th style="text-align:right;">Inputs per sample</th><th style="text-align:right;">QuickJS ms</th><th style="text-align:right;">Full ms</th><th style="text-align:right;">Lean ms</th><th style="text-align:right;">QuickJS/full</th><th style="text-align:right;">QuickJS/lean</th></tr></thead><tbody><tr><td><code>numeric</code></td><td style="text-align:right;">1,000,000</td><td style="text-align:right;">114 (113–114)</td><td style="text-align:right;">72 (71–72)</td><td style="text-align:right;">77 (77–91)</td><td style="text-align:right;">1.58x</td><td style="text-align:right;">1.48x</td></tr><tr><td><code>objects</code></td><td style="text-align:right;">50,000</td><td style="text-align:right;">15 (15–16)</td><td style="text-align:right;">12 (8–43)</td><td style="text-align:right;">13 (9–44)</td><td style="text-align:right;">1.25x</td><td style="text-align:right;">1.15x</td></tr><tr><td><code>strings</code></td><td style="text-align:right;">25,000</td><td style="text-align:right;">8 (8–9)</td><td style="text-align:right;">22 (21–23)</td><td style="text-align:right;">23 (22–28)</td><td style="text-align:right;">0.36x</td><td style="text-align:right;">0.35x</td></tr><tr><td><code>string-construction</code></td><td style="text-align:right;">25,000</td><td style="text-align:right;">8 (8–10)</td><td style="text-align:right;">19 (15–23)</td><td style="text-align:right;">22 (15–26)</td><td style="text-align:right;">0.42x</td><td style="text-align:right;">0.36x</td></tr><tr><td><code>string-join</code></td><td style="text-align:right;">25,000</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1.00x</td><td style="text-align:right;">1.00x</td></tr><tr><td><code>config-validation</code></td><td style="text-align:right;">1,000</td><td style="text-align:right;">8 (8–9)</td><td style="text-align:right;">10 (10–12)</td><td style="text-align:right;">11 (11–14)</td><td style="text-align:right;">0.80x</td><td style="text-align:right;">0.73x</td></tr><tr><td><code>command-routing</code></td><td style="text-align:right;">4,000</td><td style="text-align:right;">45 (45–46)</td><td style="text-align:right;">99 (94–100)</td><td style="text-align:right;">102 (98–104)</td><td style="text-align:right;">0.45x</td><td style="text-align:right;">0.44x</td></tr><tr><td><code>command-tokenization</code></td><td style="text-align:right;">4,000</td><td style="text-align:right;">38 (38–39)</td><td style="text-align:right;">91 (90–94)</td><td style="text-align:right;">93 (92–99)</td><td style="text-align:right;">0.42x</td><td style="text-align:right;">0.41x</td></tr><tr><td><code>command-route-lookup</code></td><td style="text-align:right;">4,000</td><td style="text-align:right;">1 (1–2)</td><td style="text-align:right;">1 (0–1)</td><td style="text-align:right;">1 (1–1)</td><td style="text-align:right;">1.00x</td><td style="text-align:right;">1.00x</td></tr><tr><td><code>permission-resolution</code></td><td style="text-align:right;">12,000</td><td style="text-align:right;">22 (21–22)</td><td style="text-align:right;">30 (27–31)</td><td style="text-align:right;">31 (27–31)</td><td style="text-align:right;">0.73x</td><td style="text-align:right;">0.71x</td></tr><tr><td><code>player-directory</code></td><td style="text-align:right;">18,000</td><td style="text-align:right;">17 (17–18)</td><td style="text-align:right;">28 (27–33)</td><td style="text-align:right;">31 (29–35)</td><td style="text-align:right;">0.61x</td><td style="text-align:right;">0.55x</td></tr><tr><td><code>event-cache</code></td><td style="text-align:right;">20,000</td><td style="text-align:right;">29 (28–30)</td><td style="text-align:right;">53 (49–55)</td><td style="text-align:right;">56 (53–59)</td><td style="text-align:right;">0.55x</td><td style="text-align:right;">0.52x</td></tr><tr><td><code>chat-formatting</code></td><td style="text-align:right;">3,000</td><td style="text-align:right;">35 (34–36)</td><td style="text-align:right;">52 (48–53)</td><td style="text-align:right;">53 (50–53)</td><td style="text-align:right;">0.67x</td><td style="text-align:right;">0.66x</td></tr><tr><td><code>scoreboard-rendering</code></td><td style="text-align:right;">12,000</td><td style="text-align:right;">103 (100–111)</td><td style="text-align:right;">154 (152–161)</td><td style="text-align:right;">164 (160–170)</td><td style="text-align:right;">0.67x</td><td style="text-align:right;">0.63x</td></tr><tr><td><code>region-protection</code></td><td style="text-align:right;">20,000</td><td style="text-align:right;">21 (20–21)</td><td style="text-align:right;">28 (28–29)</td><td style="text-align:right;">28 (28–29)</td><td style="text-align:right;">0.75x</td><td style="text-align:right;">0.75x</td></tr><tr><td><code>world-edit-plan</code></td><td style="text-align:right;">55,296</td><td style="text-align:right;">23 (23–24)</td><td style="text-align:right;">11 (11–12)</td><td style="text-align:right;">12 (11–12)</td><td style="text-align:right;">2.09x</td><td style="text-align:right;">1.92x</td></tr><tr><td><code>economy-transfers</code></td><td style="text-align:right;">12,000</td><td style="text-align:right;">145 (143–153)</td><td style="text-align:right;">14 (9–19)</td><td style="text-align:right;">16 (10–20)</td><td style="text-align:right;">10.36x</td><td style="text-align:right;">9.06x</td></tr><tr><td><code>inventory-stacking</code></td><td style="text-align:right;">2,500</td><td style="text-align:right;">11 (10–11)</td><td style="text-align:right;">5 (4–6)</td><td style="text-align:right;">5 (4–6)</td><td style="text-align:right;">2.20x</td><td style="text-align:right;">2.20x</td></tr><tr><td><code>cooldown-rate-limit</code></td><td style="text-align:right;">20,000</td><td style="text-align:right;">12 (11–12)</td><td style="text-align:right;">16 (15–17)</td><td style="text-align:right;">17 (16–21)</td><td style="text-align:right;">0.75x</td><td style="text-align:right;">0.71x</td></tr><tr><td><code>tick-scheduler</code></td><td style="text-align:right;">6,000</td><td style="text-align:right;">10 (10–11)</td><td style="text-align:right;">8 (5–9)</td><td style="text-align:right;">9 (5–10)</td><td style="text-align:right;">1.25x</td><td style="text-align:right;">1.11x</td></tr><tr><td><code>audit-history</code></td><td style="text-align:right;">13,000</td><td style="text-align:right;">73 (72–75)</td><td style="text-align:right;">9 (5–10)</td><td style="text-align:right;">9 (5–10)</td><td style="text-align:right;">8.11x</td><td style="text-align:right;">8.11x</td></tr><tr><td><code>player-state-json</code></td><td style="text-align:right;">1,200</td><td style="text-align:right;">17 (17–19)</td><td style="text-align:right;">12 (7–13)</td><td style="text-align:right;">12 (8–14)</td><td style="text-align:right;">1.42x</td><td style="text-align:right;">1.42x</td></tr><tr><td><code>custom-payload</code></td><td style="text-align:right;">16,384</td><td style="text-align:right;">4 (3–4)</td><td style="text-align:right;">2 (2–2)</td><td style="text-align:right;">2 (2–2)</td><td style="text-align:right;">2.00x</td><td style="text-align:right;">2.00x</td></tr><tr><td><code>pumpkin-api</code></td><td style="text-align:right;">10,000</td><td style="text-align:right;">11 (11–12)</td><td style="text-align:right;">39 (38–44)</td><td style="text-align:right;">39 (39–44)</td><td style="text-align:right;">0.28x</td><td style="text-align:right;">0.28x</td></tr></tbody></table><p>In this run, full Hermes had a lower median than QuickJS on 9 rows, QuickJS had a lower median on 13, and 2 displayed as ties. Lean had the same count split. Those ties are at the reported precision; they do not establish equal execution cost. The large spread on some rows, such as object allocation, is also a reminder that a five-sample range can expose variability rather than eliminate it.</p><h2 id="what-the-results-suggest—and-what-they-do-not-prove" tabindex="-1">What the results suggest—and what they do not prove <a class="header-anchor" href="#what-the-results-suggest—and-what-they-do-not-prove" aria-label="Permalink to &quot;What the results suggest—and what they do not prove&quot;">​</a></h2><p>The linked run shows workload-specific differences, not one engine that wins every kind of work. QuickJS was faster in its command-tokenization and string-construction fixtures. Full and lean Hermes were faster in the numeric baseline and several state-processing fixtures, with especially large ratios in economy-transfers and audit-history. The real API row favored QuickJS for repeated empty-list <code>getAllPlayers()</code> calls. None of these results alone predicts a plugin’s end-to-end performance.</p><p>Several mechanisms could contribute to the pattern, but this benchmark does not profile them:</p><ul><li><strong>Bytecode and interpreter behavior.</strong> Both runtimes execute JavaScript through their own engine-specific representations and virtual machines in this WASI setup. Differences in instruction dispatch, optimization choices, and runtime implementation can affect arithmetic and control-heavy loops. The benchmark has no instruction-level profile to identify a cause.</li><li><strong>Built-in operations and strings.</strong> String construction, joining, JSON, maps, and object operations pass through different engine implementations. In the linked run, the separate join row is only about one millisecond, while construction and combined strings take longer and favor QuickJS. This is consistent with construction contributing more of the measured string difference, but the rows do not isolate every internal operation.</li><li><strong>Allocation and garbage collection.</strong> Object-heavy or state-heavy workloads may respond to object layout, allocation strategy, and collection timing. The report records no heap, allocation, or GC counters, so these remain hypotheses rather than findings.</li><li><strong>Wasm host boundary.</strong> The API row includes real Pumpkin/WIT/JSI call plumbing as well as the JavaScript call loop. Because the server has no players, it does not measure converting or traversing a large player list. It cannot distinguish host-call overhead from the other work in the call path.</li><li><strong>Workload shape.</strong> A fixture may reward one engine’s built-ins or implementation details without representing a production plugin’s data sizes, branches, object lifetimes, API calls, or tick cadence.</li></ul><p>For engine or plugin decisions, benchmark the plugin’s actual hot path with realistic data and the same production build settings. Use a profiler or targeted counters before assigning a cause to a timing difference.</p><h2 id="limits-and-interpretation-rules" tabindex="-1">Limits and interpretation rules <a class="header-anchor" href="#limits-and-interpretation-rules" aria-label="Permalink to &quot;Limits and interpretation rules&quot;">​</a></h2><ul><li>The linked table is one run of one PR merge candidate. Hardware, host load, Wasmtime/Pumpkin versions, toolchain pins, and source changes can alter results. Use the linked job for provenance and compare like-for-like revisions and environments.</li><li>The job log identifies a GitHub-hosted Ubuntu 26.04 runner but not its CPU model. Do not infer a CPU from the operating-system image.</li><li>Five samples with integer-millisecond timing can expose large differences in these workloads, but cannot resolve small differences reliably. A zero-millisecond sample is possible; ratios are unavailable when the denominator median is zero.</li><li>Engine runs are serial and always follow the same order. Changes in host load during a job can affect later variants; the comparison does not alternate engine order or repeat independent server runs.</li><li>Input counts differ by design. A million arithmetic iterations and 1,000 config validations are not equivalent units. Do not average or compare rows as if they were normalized operations.</li><li>The arithmetic mean weights all 24 workload medians equally. A single slower row can move it substantially, and changing the workload set changes its meaning.</li><li>The real API case is narrow. It measures one API method with an empty result and does not represent all Pumpkin calls or guest-to-host conversion costs.</li><li>Component size is the benchmark plugin’s final component size. Plugin imports, bundled dependencies, API usage, and build profile change the result.</li></ul><h2 id="for-runtime-and-ci-contributors" tabindex="-1">For runtime and CI contributors <a class="header-anchor" href="#for-runtime-and-ci-contributors" aria-label="Permalink to &quot;For runtime and CI contributors&quot;">​</a></h2><p>The test owns the compared variants, checksum assertions, workload counts, output format, and the GitHub job summary. When changing it:</p><ul><li>Keep workload code identical across engine builds, and preserve equal input counts and deterministic checksum checks.</li><li>Keep labels clear about provenance: guest-side synthetic fixture or real Pumpkin API.</li><li>Keep API behavior assertions separate from timed synthetic algorithms unless the API path itself is explicitly being measured.</li><li>Treat new workload rows and changes to fixture inputs as changes to the meaning of the average.</li><li>Report the runner image and source revision with any published comparison. Include CPU details only when the runner actually exposes them.</li><li>Use the runtime guide for the pinned Hermes/WASI toolchain and build configuration; use the test harness guide for server selection and startup behavior.</li></ul><p>The maintained implementation is in <a href="../test/engine-comparison.test.ts">engine-comparison.test.ts</a>, <a href="../src/benchmark-workloads.ts">benchmark-workloads.ts</a>, <a href="../src/benchmark-plugin.ts">benchmark-plugin.ts</a>, and the <a href="../../../.github/workflows/engine-comparison.yml">comparison workflow</a>. The real-server harness is documented in <a href="./../../../docs/testing">Testing</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://bellard.org/quickjs/quickjs.html" target="_blank" rel="noreferrer">QuickJS official documentation</a>: engine overview, interpreter/compiler, bytecode, and memory handling.</li><li><a href="https://github.com/facebook/hermes/blob/main/doc/BuildingAndRunning.md" target="_blank" rel="noreferrer">Hermes official build and execution guide</a>: Hermes bytecode compiler and execution modes.</li><li><a href="./../../../docs/building">Pumpkin plugin build guide</a> and <a href="./../README">Static Hermes runtime guide</a>: this repository’s component build, engine profiles, and WASI configuration.</li><li><a href="https://github.com/filiphsps/pumpkin-plugins/actions/runs/38254750702/job/114834399434?pr=99" target="_blank" rel="noreferrer">PR 99 engine-comparison job</a>: source revision, runner context, component sizes, and workload output for the example above.</li></ul>`,49)])])}const m=e(a,[["render",d]]);export{u as __pageData,m as default};
